// Docs page template for every component: autodocs blocks plus the Figma registry data generated by
// .storybook/scripts/build-docs.mjs (Figma set link, property → prop mapping, usage docs, drift, embed).
import { Controls, Description, Heading, Markdown, Primary, Stories, Subtitle, Title, Unstyled, useOf } from '@storybook/addon-docs/blocks';
import { adDesignKitDocs } from '../generated/ad-design-kit-docs';
import { DriftList, FigmaEmbed, FigmaHeader, VariantMap } from './blocks';
import { categoryLabels } from './figma';

export function ADDesignKitDocsPage() {
  const resolved = useOf('meta', ['meta']);
  const title = resolved.preparedMeta.title;
  const name = title.split('/').pop() ?? '';
  const entry = adDesignKitDocs.components[name];
  const intro = entry ? adDesignKitDocs.categoryIntro[entry.category] : '';

  return (
    <>
      <Title />
      {entry ? <Subtitle>{`${categoryLabels[entry.category] ?? entry.category} · Figma component set “${entry.figmaName}”`}</Subtitle> : null}
      <Description />
      {entry ? (
        <Unstyled>
          <FigmaHeader entry={entry} />
        </Unstyled>
      ) : null}
      <Primary />
      <Controls />
      {entry ? (
        <>
          <Heading>Figma properties → React props</Heading>
          <Unstyled>
            <VariantMap entry={entry} />
            {entry.drift.length ? <DriftList findings={entry.drift} /> : null}
          </Unstyled>
          <Heading>Usage</Heading>
          <Markdown>{entry.doc}</Markdown>
          {entry.extraDocs.map((extra) => (
            <div key={extra.react}>
              <Heading>{extra.heading}</Heading>
              {extra.figmaLine ? <Markdown>{`Figma: ${extra.figmaLine}`}</Markdown> : null}
              <Markdown>{extra.doc}</Markdown>
            </div>
          ))}
          {intro ? (
            <details>
              <summary>About {categoryLabels[entry.category]?.toLowerCase() ?? entry.category} components</summary>
              <Markdown>{intro}</Markdown>
            </details>
          ) : null}
        </>
      ) : null}
      <Stories />
      {entry?.figmaUrl ? (
        <>
          <Heading>Design reference</Heading>
          <Unstyled>
            <FigmaEmbed entry={entry} />
          </Unstyled>
        </>
      ) : null}
    </>
  );
}
